package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.sql.Timestamp;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import tools.jackson.databind.json.JsonMapper;
import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.collaboration.submissionfiles.v1.*;
final class SubmissionFilesStore {
 record File(UUID mediaId,long version,String filename,String mimeType,long byteSize,String sha256){}
 record Bundle(UUID bundleId,long version,UUID submissionId,long submissionVersion,UUID assignmentId,UUID studyId,UUID groupId,UUID spaceId,UUID authorId,List<File> files,String audience,String createdAt){}
 record View(UUID submissionId,long submissionVersion,List<File> files){}
 record Result(SubmissionStore.Submission submission,List<File> files,boolean applied){}
 private final SubmissionStore submissions;private final JdbcTemplate sql;private final TransactionTemplate tx;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 SubmissionFilesStore(DataSource source,SubmissionStore submissions,Clock clock){this.submissions=submissions;sql=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);ids=new UuidV7(clock);}
 UUID author(UUID group,UUID space,UUID study,UUID assignment,UUID id,UUID actor,boolean owner){return submissions.get(group,space,study,assignment,id,actor,owner).authorId();}
 View get(UUID group,UUID space,UUID study,UUID assignment,UUID id,long version,UUID actor,boolean owner){submissions.instructions(group,space,study,assignment,id,actor,owner,version);var rows=sql.query("SELECT snapshot::text FROM submission_file_bundle WHERE submission_id=? AND submission_version=?",(rs,n)->json.readValue(rs.getString(1),Bundle.class),id,version);return new View(id,version,rows.isEmpty()?List.of():rows.getFirst().files());}
 Result submit(UUID group,UUID space,UUID study,UUID assignment,UUID actor,long expected,long assignmentVersion,String key,String content,List<File> files,String trace){
  if(files==null||files.isEmpty()||files.size()>5||new HashSet<>(files.stream().map(File::mediaId).toList()).size()!=files.size())throw GroupInput.bad();for(var f:files)validate(f);
  return tx.execute(status->{var result=submissions.submitWithFiles(group,space,study,assignment,actor,expected,assignmentVersion,key,content,trace);var v=result.submission();if(!result.applied()){var original=get(group,space,study,assignment,v.submissionId(),v.version(),actor,false);if(!original.files().equals(files))throw new ResponseStatusException(HttpStatus.CONFLICT,"Submitted files differ from original intent");return new Result(v,original.files(),false);}
   var b=new Bundle(ids.next(),1,v.submissionId(),v.version(),assignment,study,group,space,actor,List.copyOf(files),"AUTHOR_AND_OWNER",v.updatedAt());sql.update("INSERT INTO submission_file_bundle VALUES (?,?,?,?,?,?,?,?,?::jsonb)",b.bundleId(),v.submissionId(),v.version(),assignment,study,group,space,actor,json.writeValueAsString(b));record(b,trace);return new Result(v,b.files(),true);
  });
 }
 static void validate(File f){if(f==null)throw GroupInput.bad();GroupInput.id(f.mediaId().toString());if(f.version()!=2||f.filename()==null||(!GroupInput.unicode(f.filename())||f.filename().isBlank())||f.filename().codePointCount(0,f.filename().length())>200||f.filename().codePoints().anyMatch(Character::isISOControl)||f.filename().contains("/")||f.filename().contains("\\")||f.filename().equals(".")||f.filename().equals("..")||f.mimeType()==null||!Set.of("application/octet-stream","application/pdf","image/png","image/jpeg","image/gif","image/webp").contains(f.mimeType())||f.byteSize()<1||f.byteSize()>10485760||f.sha256()==null||!f.sha256().matches("[0-9a-f]{64}"))throw GroupInput.bad();}
 private void record(Bundle b,String trace){var p=SubmissionFilesSnapshotV1.newBuilder().setBundleId(b.bundleId().toString()).setVersion(1).setSubmissionId(b.submissionId().toString()).setSubmissionVersion(b.submissionVersion()).setAssignmentId(b.assignmentId().toString()).setStudyId(b.studyId().toString()).setGroupId(b.groupId().toString()).setSpaceId(b.spaceId().toString()).setAuthorId(b.authorId().toString()).setAudience(b.audience()).setCreatedAt(b.createdAt());for(var f:b.files())p.addFiles(SubmittedFileV1.newBuilder().setMediaId(f.mediaId().toString()).setVersion(f.version()).setFilename(f.filename()).setMimeType(f.mimeType()).setByteSize(f.byteSize()).setSha256(f.sha256()));UUID id=ids.next();var now=Instant.parse(b.createdAt());var e=SubmissionFilesEnvelopeV1.newBuilder().setEventId(id.toString()).setEventType("SubmissionFilesAttached").setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("collaboration-service").setAggregateType("SubmissionFiles").setAggregateId(b.bundleId().toString()).setSpaceId(b.spaceId().toString()).setActorId(b.authorId().toString()).setTraceId(trace).setPayload(p.build().toByteString()).build();sql.update("INSERT INTO outbox_event VALUES (?,'submission-files',?,?,?,?, 'collaboration','submission-files-events','1',?)",id,b.bundleId(),"SubmissionFilesAttached",Timestamp.from(now),trace,e.toByteArray());}
}
